import{_ as r,C as i,o,c as d,j as a,a as t,E as l,a5 as n}from"./chunks/framework.DrDMl0tG.js";const _=JSON.parse('{"title":"Examples","description":"","frontmatter":{},"headers":[],"relativePath":"sections/Examples.md","filePath":"sections/Examples.md"}'),c={name:"sections/Examples.md"};function h(p,e,m,u,g,y){const s=i("ExampleGallery");return o(),d("div",null,[e[0]||(e[0]=a("h1",{id:"examples",tabindex:"-1"},[t("Examples "),a("a",{class:"header-anchor",href:"#examples","aria-label":'Permalink to "Examples"'},"​")],-1)),e[1]||(e[1]=a("p",null,[t("Examples are grouped by the feature they demonstrate, with clips recorded from the running programs. Choose a topic, then select an example to open its page; "),a("a",{href:"#run"},"Run"),t(" explains how to build and run them.")],-1)),l(s),e[2]||(e[2]=n(`<h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The <code>raisim2Lib</code> distribution ships prebuilt RaiSim and rayrai libraries together with C++ example sources. Build the examples with CMake. The install target does not copy the example executables, and the package does not include a prebuilt TCP viewer: the <code>rayrai_tcp_viewer</code> target builds it from the example sources.</p><p>The examples fall into three kinds:</p><ul><li><strong>Server examples</strong>, such as <code>primitive_grid</code>, build a <code>raisim::World</code> and publish it through <code>raisim::RaisimServer</code>. View them with <code>rayrai_tcp_viewer</code>.</li><li><strong>Rayrai examples</strong>, such as <code>rayrai_pbr_material_grid</code>, render in process with <code>raisin::RayraiWindow</code>.</li><li><strong>Non-visual tools and benchmarks</strong>, such as <code>model_asset_pipeline</code> and <code>articulated_system_benchmark</code>, print results or write files.</li></ul><p>Together they cover the RaiSim physics APIs, mesh import and export, OpenUSD loading, and rayrai rendering and asset inspection. RaisimUnity and RaisimUnreal are no longer supported; see <a href="./LegacyIntegrations.html">Legacy Integrations</a>.</p><p>For optional manual regression and debug programs, see <a href="./DebugTools.html">Regression and Debug Tools</a>.</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><p>After the top-level build from <a href="./BuildAndTest.html">Build, Test, and Benchmark</a>, run examples from the build tree:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/primitive_grid</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/rayrai_pbr_material_grid</span></span></code></pre></div><p>On Windows, the executables are in <code>build-examples\\bin</code>:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\build-examples</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\\bin\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">primitive_grid.exe</span></span></code></pre></div><p>If the runtime loader cannot find the shared libraries, set up the environment before running examples. On Linux and macOS, <code>raisim_env.sh</code> sets <code>LD_LIBRARY_PATH</code> or <code>DYLD_LIBRARY_PATH</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/raisim2Lib/raisim_env.sh</span></span></code></pre></div><p>On Windows, CMake copies the runtime DLLs next to the executables. If a DLL is still missing, add the package directories to <code>PATH</code> from PowerShell or from the Command Prompt:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\raisim_env.ps1</span></span></code></pre></div><div class="language-batch vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">batch</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">raisim_env.bat</span></span></code></pre></div><h2 id="visualization-modes" tabindex="-1">Visualization modes <a class="header-anchor" href="#visualization-modes" aria-label="Permalink to &quot;Visualization modes&quot;">​</a></h2><p>There are two visualization paths. See <a href="./Visualization.html">Visualization</a> for the full workflow comparison.</p><h3 id="raisimserver-examples" tabindex="-1">RaisimServer examples <a class="header-anchor" href="#raisimserver-examples" aria-label="Permalink to &quot;RaisimServer examples&quot;">​</a></h3><p>Server examples such as <code>primitive_grid</code> create a RaiSim world and publish it through <code>raisim::RaisimServer</code>. They do not open a renderer window themselves. Start the source-built viewer, then run the server example:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Terminal 1</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/rayrai_tcp_viewer</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Terminal 2</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/primitive_grid</span></span></code></pre></div><p>The default server port is <code>8080</code> unless the example changes it. Use this path when you want to inspect the same simulation data that a normal RaisimServer application publishes.</p><h3 id="rayrai-examples" tabindex="-1">Rayrai examples <a class="header-anchor" href="#rayrai-examples" aria-label="Permalink to &quot;Rayrai examples&quot;">​</a></h3><p>Examples such as <code>rayrai_pbr_material_grid</code>, <code>rayrai_pbr_texture_maps</code>, and <code>rayrai_visual_asset_support</code> create or use a <code>raisin::RayraiWindow</code> directly and render in process. They do not need the TCP viewer:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/rayrai_pbr_material_grid</span></span></code></pre></div><p>Prefer these examples when you need camera images, GPU/offscreen rendering, PBR materials, glTF visual import, or standalone rayrai feature inspection. USD visual meshes can also be loaded through <code>RayraiWindow::addVisualMesh</code>; see <a href="./OpenUSD.html">OpenUSD Loading</a> for the importer scope.</p><h3 id="non-visual-examples" tabindex="-1">Non-visual examples <a class="header-anchor" href="#non-visual-examples" aria-label="Permalink to &quot;Non-visual examples&quot;">​</a></h3><p>Some examples print output or create files instead of showing a window. <code>model_asset_pipeline</code> writes preprocessed and exported OBJ files to <code>raisim_model_asset_pipeline_example</code> in the system temporary directory (<code>/tmp</code> on Linux). <code>articulated_system_benchmark</code> and <code>anymal_standing_benchmark</code> print timing results.</p><h2 id="example-layout" tabindex="-1">Example layout <a class="header-anchor" href="#example-layout" aria-label="Permalink to &quot;Example layout&quot;">​</a></h2><p>The examples project groups targets by executable behavior:</p><table tabindex="0"><thead><tr><th>Group</th><th>Purpose</th></tr></thead><tbody><tr><td>Server examples</td><td>RaiSim physics, contact, terrain, sensor, robot, XML/MJCF, and OpenUSD scene workflows published through <code>RaisimServer</code>.</td></tr><tr><td><code>rayrai_*</code></td><td>In-process rayrai renderer examples and the <code>rayrai_tcp_viewer</code> tool.</td></tr><tr><td>Benchmark examples</td><td>Timing runs for articulated-system, contact, and sleeping-island workloads.</td></tr></tbody></table><h2 id="choosing-an-example" tabindex="-1">Choosing an example <a class="header-anchor" href="#choosing-an-example" aria-label="Permalink to &quot;Choosing an example&quot;">​</a></h2><p>Start with these targets when learning a specific feature:</p><table tabindex="0"><thead><tr><th>Target</th><th>Demonstrates</th></tr></thead><tbody><tr><td><code>primitive_grid</code></td><td>Basic rigid primitive creation and RaisimServer publishing.</td></tr><tr><td><code>model_asset_pipeline</code></td><td>Mesh preprocessing, content-hash cache reuse, <code>addMesh</code> with processed assets, and OBJ export from a world.</td></tr><tr><td><code>shadow_hand_usd_cube</code></td><td>Loading an OpenUSD ShadowHand scene through <code>World(shadow_hand.usd)</code>, adding a native RaiSim cube, and publishing both through <code>RaisimServer</code>.</td></tr><tr><td><code>nvidia_usd_robots</code></td><td>Loading vetted NVIDIA Isaac Sim robot USD files with <code>World::addUsdArticulatedSystem</code> and publishing them through <code>RaisimServer</code>.</td></tr><tr><td><code>rayrai_pbr_material_grid</code></td><td>Inspecting metallic-roughness PBR material behavior under rayrai.</td></tr><tr><td><code>rayrai_visual_asset_support</code></td><td>Rendering textured URDF visual meshes (OBJ/DAE with image textures) separately from their collision geometry.</td></tr><tr><td><code>rayrai_coacd_mesh_approximation</code></td><td>Visually comparing original meshes and CoACD convex approximation parts generated through <code>World::addMesh</code>. The first run can take a few minutes while CoACD generates and caches the parts.</td></tr><tr><td><code>rayrai_tcp_viewer</code></td><td>The TCP visualizer used by RaisimServer examples.</td></tr><tr><td><code>tendon_elastic</code>, <code>tendon_pulleys</code>, <code>tendon_coupling</code></td><td>Elastic suspensions, routed guides/pulley branches, and joint transmissions. See <a href="./tendons/Examples.html">Tendon examples and Rayrai</a>.</td></tr><tr><td><code>rayrai_tendons</code></td><td>Automatic tendon rendering with scene selection, pause/step/reset, and live transmission values. See <a href="./Tendons.html">Tendons</a>.</td></tr><tr><td><code>rayrai_inverse_kinematics</code></td><td>Mouse-driven inverse kinematics: drag and turn a target, and <code>ArticulatedSystem::solveIK()</code> drives a simulated Kinova arm with a Robotiq gripper after it, through joint PD targets, to push, grasp and lift cubes. See <a href="./examples/rayrai/rayrai_inverse_kinematics.html">Rayrai Example: Inverse Kinematics</a>.</td></tr><tr><td><code>robotiq_cloth_fold</code></td><td>A Kinova arm with a Robotiq 2F-85 lays a cloth on the table and folds it in half: deformable cloth in contact with gripper pads, a table and itself, and fold waypoints solved with <code>ArticulatedSystem::solveIK()</code> from where the cloth landed. See <a href="./examples/server/robotiq_cloth_fold.html">Server Example: Robotiq Cloth Fold</a>.</td></tr><tr><td><code>heavy_objects_on_cloth</code></td><td>A 10 kg ball on a cloth, a 5 kg box on two stacked cloths, and a 5 kg blanket over a 1 kg box, with the cloth solved together with the bodies, so each load rests on what carries the cloth. See <a href="./examples/server/heavy_objects_on_cloth.html">Server Example: Heavy Objects on Cloth</a>.</td></tr><tr><td><code>cloth_on_slope</code></td><td>A box on a cloth on two ramps: below the friction angle both stay, above it they slide together. See <a href="./examples/server/cloth_on_slope.html">Server Example: Cloth on a Slope</a>.</td></tr><tr><td><code>tablecloth_pull</code></td><td>The tablecloth trick: a sharp pull whips a cloth out from under three dishes, which stay on the table. See <a href="./examples/server/tablecloth_pull.html">Server Example: Tablecloth Pull</a>.</td></tr><tr><td><code>rayrai_deformable_terrain</code></td><td>An off-road buggy drives across deformable soil, leaving permanent wheel ruts. See <a href="./examples/rayrai/rayrai_deformable_terrain.html">Rayrai Example: Deformable Terrain</a>.</td></tr><tr><td><code>rayrai_motor_operating_region</code></td><td>Actuators with motor operating regions (EM-MOR), linked from the URDF as actuator files, with live torque-speed plots for the twelve motors of a randomly actuated quadruped rig. See <a href="./examples/rayrai/rayrai_motor_operating_region.html">Rayrai Example: Motor Operating Region</a>.</td></tr><tr><td><code>rayrai_forest</code></td><td>Dense instanced vegetation on a heightmap with automatic mesh LOD, foliage wind and shadows, and asynchronous loading. See <a href="./examples/rayrai/rayrai_forest.html">Rayrai Example: Forest</a> for the required rayrai version.</td></tr><tr><td><code>rayrai_forest_from_rscene</code></td><td>The same forest built from its saved RaiSim Engine <code>.rscene</code> file with <code>raisim::World(path)</code> and shown by a <code>RayraiWindow</code>. Requires RaiSim and rayrai v2.8.2 (not yet released); see <a href="./examples/rayrai/rayrai_forest_from_rscene.html">Rayrai Example: Forest From .rscene</a> and <a href="./RsceneFile.html">.rscene File</a>.</td></tr><tr><td><code>rayrai_city</code></td><td>A photoreal city of modular buildings, streets and parked cars loaded from <code>rsc/city/rayrai_city.rscene</code>, with an ANYmal C quadruped added in C++. See <a href="./examples/rayrai/rayrai_city.html">Rayrai Example: City</a>.</td></tr><tr><td><code>rayrai_city_from_xml</code></td><td>The same city and robot from one RaiSim XML world file, which describes the ANYmal C and includes the city&#39;s <code>.rscene</code> file. See <a href="./examples/rayrai/rayrai_city_from_xml.html">Rayrai Example: City From XML</a>.</td></tr><tr><td><code>rayrai_warehouse</code></td><td>A photoreal warehouse of pallet racks, forklifts and a dock area loaded from <code>rsc/warehouse/rayrai_warehouse.rscene</code>, with an ANYmal C quadruped added in C++. See <a href="./examples/rayrai/rayrai_warehouse.html">Rayrai Example: Warehouse</a>.</td></tr><tr><td><code>rayrai_water_pond</code></td><td>A pond in a meadow drawn with rayrai water: ripples, the sun glittering on the surface, reflections of the banks and a green tint that hides the floor with depth, with grass, trees, rocks and a wooden jetty on its banks. See <a href="./examples/rayrai/rayrai_water_pond.html">Rayrai Example: Water Pond</a>.</td></tr><tr><td><code>rayrai_water_stream</code></td><td>A creek running down a hillside into a pool, simulated as shallow water on the GPU: the water parts around mossy rocks, foams where it runs fast and fills the pool, and wooden balls ride the current with buoyancy and drag from <code>sampleWaterFlow()</code>. See <a href="./examples/rayrai/rayrai_water_stream.html">Rayrai Example: Water Stream</a>.</td></tr><tr><td><code>rayrai_offroad_buggy</code></td><td>An off-road buggy with double-wishbone suspension, coilovers and rack-and-pinion steering, all in one URDF closed by pin, equality and mimic constraints, driven with the arrow keys on a dirt race circuit with pits, tyre walls, hay bales, cones and spectator stands; <code>--validate</code> checks its physics. See <a href="./examples/rayrai/rayrai_offroad_buggy.html">Rayrai Example: Off-Road Buggy</a>.</td></tr></tbody></table><h3 id="targets-without-a-dedicated-page" tabindex="-1">Targets without a dedicated page <a class="header-anchor" href="#targets-without-a-dedicated-page" aria-label="Permalink to &quot;Targets without a dedicated page&quot;">​</a></h3><p>These targets are built with the others but are documented only here or on a feature page:</p><table tabindex="0"><thead><tr><th>Target</th><th>Demonstrates</th></tr></thead><tbody><tr><td><code>heightmap_mesh_drop</code></td><td>Twenty monkey meshes with triangle-mesh collision dropped one at a time onto a colored procedural heightmap.</td></tr><tr><td><code>blocky_heightmap_drop</code></td><td>900 primitives and convex-hull meshes dropped onto a heightmap made of flat 0.4 m tiles.</td></tr><tr><td><code>large_scale_ray_test</code></td><td>Repeated ray queries against walls and pillars; see <a href="./RayTest.html">Ray Test</a>.</td></tr><tr><td><code>rayrai_blue_wall_scene</code></td><td>An authored glTF interior with its light sidecar and HDR environment, described by <code>rsc/rayrai/blue_wall/blue_wall.rscene</code>. The example reads that file with its own parser; <code>raisim::World(path)</code> and a <code>RayraiWindow</code> on that world load it as well (see <a href="./RsceneFile.html">.rscene File</a>). <code>--screenshot PNG</code> renders in a hidden window, saves the image, and exits.</td></tr></tbody></table><h2 id="runtime-assets" tabindex="-1">Runtime assets <a class="header-anchor" href="#runtime-assets" aria-label="Permalink to &quot;Runtime assets&quot;">​</a></h2><p>Some targets depend on bundled assets or platform runtime packages:</p><ul><li>OpenUSD loading uses the package&#39;s bundled OpenUSD runtime and USD files; keep the <code>openusd</code> runtime directory and <code>rsc</code> assets with the installed package.</li><li>Rayrai examples require SDL2/OpenGL and rayrai runtime libraries. See <a href="./Rayrai.html#platform-support">Platform support</a> for the OpenGL requirements and the reduced macOS feature set.</li><li>Poly Haven and PBR asset examples require the corresponding assets under <code>rsc</code>. CMake copies <code>rsc</code> next to the executables (<code>build-examples/examples/rsc</code>, or <code>build-examples/bin/rsc</code> on Windows).</li><li><code>rayrai_forest</code> reads its assets from <code>rsc/forest</code> in the configured checkout and writes regenerable <code>rayrai_cache_*.lods</code> files beside them. <code>rayrai_forest_from_rscene</code> reads <code>rsc/forest/rayrai_forest.rscene</code> from the <code>rsc</code> copy next to the executables, and the scene references the same assets.</li><li><code>rayrai_city</code> reads <code>rsc/city/rayrai_city.rscene</code> from the <code>rsc</code> copy next to the executables (<code>--scene</code> picks another file). Its street trees are the forest&#39;s, so it also needs <code>rsc/forest</code>. <code>rayrai_city_from_xml</code> reads <code>rsc/xmlScripts/rscene/anymal_in_city.xml</code>, which includes the same scene.</li><li><code>rayrai_warehouse</code> reads <code>rsc/warehouse/rayrai_warehouse.rscene</code> the same way. It reuses the city&#39;s sky, asphalt and traffic cones, so it also needs <code>rsc/city</code>.</li><li><code>rayrai_offroad_buggy</code> reads <code>rsc/offroad_buggy</code> (the car, its URDF, the terrain and the race venue&#39;s props), places the trees, rocks and grass of <code>rsc/forest</code>, and uses the sky and cars of <code>rsc/city</code> and the barrels of <code>rsc/warehouse</code>.</li><li><code>rayrai_water_pond</code> places the plants and rocks of <code>rsc/forest</code>.</li><li><code>rayrai_water_stream</code> places the plants and rocks of <code>rsc/forest</code> and gives the rocks in the creek colliders from the same models.</li><li><code>rayrai_coacd_mesh_approximation</code> writes <code>raisim_coacd_*</code> cache files beside the YCB meshes in the build tree&#39;s <code>rsc</code> copy.</li></ul><p>After building, list the example executables from the platform-specific output directory. Linux and macOS builds place them under <code>examples</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build-examples/examples/</span></span></code></pre></div><p>Windows builds place them under <code>bin</code>:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-ChildItem</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> .</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\build-examples</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\\bin\\</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.exe</span></span></code></pre></div>`,44))])}const f=r(c,[["render",h]]);export{_ as __pageData,f as default};
